#!/bin/sh
# Runs INSIDE a Debian 12 arm64 container with the FULL ffmpeg (tests/test_streamtools_docker.sh starts it): makes the small original media the stream-tool tests
# serve from a local web server, into /fx. Generated by lavfi test sources: no third-party content.
set -eu
apt-get update -qq >/dev/null 2>&1
apt-get install -y -qq --no-install-recommends ffmpeg >/dev/null 2>&1 || { echo "fixtures: apt install ffmpeg failed" >&2; exit 1; }
cd /fx
rm -rf ./*
ff() { ffmpeg -v error -y "$@"; }
tv() { ff -f lavfi -i testsrc2=s=320x240:r=25:d=3 -f lavfi -i sine=f=440:d=3 "$@"; }   # three seconds of test picture and a tone
# a progressive MP4 with its index first (streamable) and one with it last (not)
tv -c:v libx264 -pix_fmt yuv420p -c:a aac -movflags +faststart clip.mp4
tv -c:v libx264 -pix_fmt yuv420p -c:a aac clip-nofast.mp4
# DASH, separate video and audio (what a site serves for its better qualities): H.264 + AAC, and VP9 + Opus
mkdir dash-avc dash-vp9
ff -i clip.mp4 -c copy -f dash -seg_duration 1 -use_template 1 -use_timeline 1 -adaptation_sets "id=0,streams=v id=1,streams=a" dash-avc/manifest.mpd
tv -c:v libvpx-vp9 -b:v 200k -c:a libopus -f dash -seg_duration 1 -use_template 1 -use_timeline 1 -adaptation_sets "id=0,streams=v id=1,streams=a" dash-vp9/manifest.mpd
# HLS, plain and AES-128 encrypted (the key is a file next to the playlist)
mkdir hls hls-aes
ff -i clip.mp4 -c copy -f hls -hls_time 1 -hls_playlist_type vod -hls_segment_filename 'hls/seg%d.ts' hls/index.m3u8
head -c 16 /dev/urandom > hls-aes/key.bin
IV="$(od -An -tx1 -N16 /dev/urandom | tr -d ' \n')"
printf 'key.bin\n/fx/hls-aes/key.bin\n%s\n' "$IV" > /tmp/keyinfo
ff -i clip.mp4 -c copy -f hls -hls_time 1 -hls_playlist_type vod -hls_key_info_file /tmp/keyinfo -hls_segment_filename 'hls-aes/seg%d.ts' hls-aes/index.m3u8
grep -q 'METHOD=AES-128' hls-aes/index.m3u8 || { echo "fixtures: the HLS playlist is not encrypted" >&2; exit 1; }
# a still, for gallery-dl
ff -f lavfi -i testsrc2=s=64x48 -frames:v 1 pic.png
find /fx -type f | sort | head -60
echo "fixtures: done"
